        return sum(d["content"][n][f] * m.servings[f] for f in m.FOODS) >= d["requirement"][n]

    model.nutrient_requirement = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "foods": ["chicken", "rice", "tofu", "spinach", "almonds", "salmon"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "chicken": 4,
        "rice": 10,
        "tofu": 6,
        "spinach": 1,
        "almonds": 8,
        "salmon": 6,
    },
    "content": {
        "protein": {
            "chicken": 14, "rice": 11, "tofu": 20,
            "spinach": 6, "almonds": 9, "salmon": 20,
        },
        "carbs": {
            "chicken": 4, "rice": 17, "tofu": 12,
            "spinach": 20, "almonds": 11, "salmon": 19,
        },
        "calories": {
            "chicken": 275, "rice": 151, "tofu": 155,
            "spinach": 106, "almonds": 279, "salmon": 93,
        },
    },
    "requirement": {"protein": 78, "carbs": 140, "calories": 1537},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.x = pyo.Var(model.I, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        # sum of nutrient n across foods must be >= requirement  -> lower bound
        return sum(d["content"][n][i] * m.x[i] for i in m.I) >= d["requirement"][n]

    model.nutrient = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
